def find_sequence(n):
    for a1 in range(1, n):
        for a2 in range(1, n):
            if (a1 + a2) % n != 0:
                sequence = [a1, a2]
                valid = True
                for i in range(2, n):
                    a_next = n - (sum(sequence[-i:]) % n)
                    sequence.append(a_next)
                    for j in range(i+1):
                        if sum(sequence[j:i+1]) % n == 0:
                            valid = False
                            break
                    if not valid:
                        break
                if valid and sum(sequence) % n != 0:
                    return sequence
    return None

sequence = find_sequence(30)
